package com.myblog.user.controller;
import com.myblog.user.common.ApiResult;import com.myblog.user.service.UserProfileService;import com.myblog.user.vo.*;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.List;
@RestController @RequestMapping("/api") public class UserProfileController{private final UserProfileService service;public UserProfileController(UserProfileService s){service=s;}@GetMapping("/profile/me")public ApiResult<UserProfileVO> me(@RequestAttribute("userId")Long id){return ApiResult.success(service.me(id));}@PostMapping(value="/profile/avatar",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ApiResult<UserProfileVO> upload(@RequestAttribute("userId")Long id,@RequestParam("file")MultipartFile f){return ApiResult.success("头像已更新",service.uploadAvatar(id,f));}@DeleteMapping("/profile/avatar")public ApiResult<UserProfileVO> delete(@RequestAttribute("userId")Long id){return ApiResult.success("头像已删除",service.deleteAvatar(id));}@GetMapping("/users/{id}/avatar/file")public ResponseEntity<Resource> avatar(@PathVariable("id")Long id){var a=service.readAvatar(id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(a.mimeType())).contentLength(a.size()).cacheControl(CacheControl.noStore()).header("X-Content-Type-Options","nosniff").body(a.resource());}@GetMapping("/users/following")public ApiResult<List<FollowedAuthorVO>> following(@RequestAttribute("userId")Long id){return ApiResult.success(service.following(id));}@GetMapping("/users/{id}/public-profile")public ApiResult<PublicUserProfileVO> publicProfile(@PathVariable("id")Long id,@RequestAttribute("userId")Long viewer){return ApiResult.success(service.publicProfile(id,viewer));}}
